    updateMatrixWorld(visibleOnly) {
      if (visibleOnly && !this.visible) return this;
      this.updateMatrix();
      if (this.parent === null) this.matrixWorld.copy(this.matrix);
      else this.matrixWorld.multiplyMatrices(this.parent.matrixWorld, this.matrix);
      for (var i = 0; i < this.children.length; i++) this.children[i].updateMatrixWorld(visibleOnly);
      return this;
    }
    localToWorld(v) { return v.applyMatrix4(this.matrixWorld); }
    getWorldPosition(target) { return target.setFromMatrixPosition(this.matrixWorld); }
