      m.specularColor.copy(this.specularColor);
      m.ao = this.ao;
      m.metalness = this.metalness;
      m.detail = this.detail;
      m.textureTile = this.textureTile;
      m.textureScale = this.textureScale;
      m.textureMix = this.textureMix;
      m.bump = this.bump;
      m.surfaceType = this.surfaceType;
      m.radiance = this.radiance;
      m.viewModel = this.viewModel;
      m.opacity = this.opacity;
      m.transparent = this.transparent;
      m.wireframe = this.wireframe;
      m.unlit = this.unlit;
      m.depthTest = this.depthTest;
      m.depthWrite = this.depthWrite;
