      this.image = image || null;
      this.flipY = !!opts.flipY;
      this.needsUpdate = true;
      this._glTexture = null;
      this._glOwner = null;
      this.width = image && image.width ? image.width : 1;
      this.height = image && image.height ? image.height : 1;
