      if (this.staticShadowReady) return;
      sun.copy(dir).normalize();
      var right = this.sunRight.set(sun.z, 0, -sun.x).normalize();
      var up = this.sunUp.crossVectors(sun, right).normalize();
      // Fixed orthographic coverage around the playable quay (x ±23, z -46
      // to 21), tall cranes and the upstream region they shadow from.
      var x = 0, y = 3, z = -13;
      var w = 44, h = 24, d = 59;
      var e = this.sunMatrix.elements;
      e[0] = right.x / w; e[4] = right.y / w; e[8] = right.z / w;
      e[12] = -(right.x * x + right.y * y + right.z * z) / w;
      e[1] = up.x / h; e[5] = up.y / h; e[9] = up.z / h;
      e[13] = -(up.x * x + up.y * y + up.z * z) / h;
      e[2] = -sun.x / d; e[6] = -sun.y / d; e[10] = -sun.z / d;
