      var size = this.shadowSize;
      if (!this.staticShadow) return null;
      var source = this.staticShadow;
      this.shadowDraws = 0;
      if (this.staticShadowReady && this.movingCasters.length === 0) return source;
      this.setSunDirection(dirLight ? dirLight.position : this.sun);
      gl.viewport(0, 0, size, size);
      gl.enable(gl.DEPTH_TEST);
      gl.depthMask(true);
      gl.disable(gl.BLEND);
