          for (var i = 0; i < 16; i += 4) { e[i] *= 1.64; e[i + 1] *= 1.40; }
          gl.bindFramebuffer(gl.FRAMEBUFFER, this.nearStatic.framebuffer);
          gl.clear(gl.DEPTH_BUFFER_BIT);
          this.drawCasters(renderer, this.staticCasters, this.nearSunMatrix);
