        gl.bindFramebuffer(gl.DRAW_FRAMEBUFFER, this.combinedShadow.framebuffer);
        gl.blitFramebuffer(0, 0, size, size, 0, 0, size, size, gl.DEPTH_BUFFER_BIT, gl.NEAREST);
