        gl.bindTexture(gl.TEXTURE_2D, reflection && reflection.valid ? reflection.target.texture : this.skyColor.texture);
        gl.uniform1f(index === 2 ? u.uReflectRaised : index ? u.uReflectDeck : u.uReflectSea, reflection && reflection.valid ? 1 : 0);
