      gl.disable(gl.DEPTH_TEST);
      gl.useProgram(this.sky.program);
      gl.uniformMatrix4fv(u.uCameraWorld, false, camera.matrixWorld.elements);
      gl.uniform2f(u.uPerspective, 1 / camera.projectionMatrix.elements[0], 1 / camera.projectionMatrix.elements[5]);
