        gl.disable(gl.BLEND);
        gl.useProgram(this.fxaaProgram.program);
        gl.activeTexture(gl.TEXTURE0);
        gl.bindTexture(gl.TEXTURE_2D, this.ldr.texture);
        gl.uniform1i(this.fxaaProgram.uniforms.uImage, 0);
